import{_ as t,o as d,c as o,a2 as s}from"./chunks/framework.YiAtXB4p.js";const u=JSON.parse('{"title":"SDE testing scorecard","description":"","frontmatter":{"title":"SDE testing scorecard","sourceFile":"guides/sde/TESTING.md"},"headers":[],"relativePath":"guide/sde-testing.md","filePath":"guide/sde-testing.md"}'),r={name:"guide/sde-testing.md"};function a(i,e,n,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="sde-testing-scorecard" tabindex="-1">SDE testing scorecard <a class="header-anchor" href="#sde-testing-scorecard" aria-label="Permalink to &quot;SDE testing scorecard&quot;">​</a></h1><p>What protects <code>src/sde</code>, measured. The Static Data Export module ships as its own sub-paths (<code>./sde</code>, <code>./sde/memory</code>), shares no code with the HTTP pipeline, and is scored, ratcheted and restored on its own in every tier the core has. This page is the SDE&#39;s copy of the core&#39;s <a href="./testing#where-the-suite-stands">Where the suite stands</a> and <a href="./testing#where-the-scores-stand">Where the scores stand</a>: one table per tier, the command that reproduces it, and the floor that holds it.</p><p>The first three suite rows, the coverage and the specification counts were re-measured on 2026-10-08 after Run M merged; the mutation section says where each score comes from, and the remaining rows were measured on <code>e4daf989</code> on 2026-09-28. The SDE&#39;s own docs, the module&#39;s role and its isolation rule are in <a href="./sde">SDE.md</a>.</p><h2 id="where-the-suite-stands" tabindex="-1">Where the suite stands <a class="header-anchor" href="#where-the-suite-stands" aria-label="Permalink to &quot;Where the suite stands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Config</th><th style="text-align:right;">Suites</th><th style="text-align:right;">Tests</th><th>Result</th></tr></thead><tbody><tr><td><code>npx jest --config config/jest/unit.config.cjs tests/tdd/sde</code></td><td><code>config/jest/unit.config.cjs</code></td><td style="text-align:right;">17</td><td style="text-align:right;">609</td><td>All pass but one, about 7 s; the <code>./sde/memory</code> bundle test skips until <code>npm run build</code> has made <code>dist/</code></td></tr><tr><td><code>npm run bdd:sde</code></td><td>same</td><td style="text-align:right;">23</td><td style="text-align:right;">227</td><td>All pass, about 9 s; every scenario executes (<code>bdd:report</code>)</td></tr><tr><td><code>npx jest --config config/jest/unit.config.cjs sde</code></td><td>same</td><td style="text-align:right;">43</td><td style="text-align:right;">1,001</td><td>The two above plus <code>sde-bench</code>, <code>sde-drift</code> and <code>sde-spec-coverage</code> under <code>tests/tdd/</code>, about 22 s</td></tr><tr><td><code>npx jest --config config/jest/fuzz.config.cjs sde</code></td><td><code>config/jest/fuzz.config.cjs</code></td><td style="text-align:right;">3</td><td style="text-align:right;">249</td><td>All pass, about 18 s; 100 runs per property on a pull request, 10,000 in <code>nightly-properties.yml</code></td></tr><tr><td><code>npx jest --config config/jest/integration.config.cjs sde</code></td><td><code>config/jest/integration.config.cjs</code></td><td style="text-align:right;">1</td><td style="text-align:right;">114</td><td>Skip without <code>sde-data/</code>; all 114 pass against CCP&#39;s current export in <a href="https://github.com/lgriffin/ESI.ts/actions/runs/36404108879" target="_blank" rel="noreferrer"><code>nightly-sde.yml</code></a></td></tr><tr><td><code>npm run test:types</code></td><td>tsd</td><td style="text-align:right;">2</td><td style="text-align:right;">—</td><td><code>sde.test-d.ts</code> and <code>sde-memory.test-d.ts</code>, 801 and 603 lines of <code>expectType</code> / <code>expectError</code> assertions over the two entry points</td></tr><tr><td><code>npm run test:consumer</code></td><td><code>tests/consumer/</code></td><td style="text-align:right;">2</td><td style="text-align:right;">—</td><td>Steps 7 and 8: <code>./sde</code> loads without <code>js-yaml</code> and <code>adm-zip</code> and names the missing one; with them installed it reads real YAML and ZIP, CJS and ESM</td></tr></tbody></table><p>The unit suites are one per module: the <code>IStaticDataProvider</code> contract (94 tests over the 96 methods, null and empty returns and the typing of each), <code>MemorySdeProvider</code>, <code>SdeDataProvider</code>, <code>SdeTestDataFactory</code>, <code>schemas</code>, <code>errors</code>, <code>clock</code>, <code>optionalPeers</code>, <code>order</code>, <code>index</code>, the <code>./sde/memory</code> bundle test, and six under <code>ingestion/</code> (<code>SdeDownloader</code>, <code>SdeExtractor</code>, <code>SdeDatabaseBuilder</code>, <code>transforms</code>, <code>registry</code>, <code>index</code>).</p><table tabindex="0"><thead><tr><th>Coverage over <code>src/sde/**</code> (excluding <code>src/sde/testing/</code>)</th><th style="text-align:right;">Unit suites alone</th><th style="text-align:right;">Unit and BDD together</th><th style="text-align:right;">Floor (<code>config/jest/unit.config.cjs</code>)</th></tr></thead><tbody><tr><td>Statements</td><td style="text-align:right;">98.45%</td><td style="text-align:right;">99.88%</td><td style="text-align:right;">90%</td></tr><tr><td>Branches</td><td style="text-align:right;">98.26%</td><td style="text-align:right;">98.26%</td><td style="text-align:right;">80%</td></tr><tr><td>Functions</td><td style="text-align:right;">97.28%</td><td style="text-align:right;">97.28%</td><td style="text-align:right;">75%</td></tr><tr><td>Lines</td><td style="text-align:right;">98.65%</td><td style="text-align:right;">100.00%</td><td style="text-align:right;">90%</td></tr></tbody></table><p>Reproduce with <code>npx jest --config config/jest/unit.config.cjs --coverage --collectCoverageFrom=&#39;src/sde/**/*.ts&#39; --collectCoverageFrom=&#39;!src/sde/testing/**&#39; tests/tdd/sde tests/bdd/specs/sde</code>. The floors are the repository&#39;s; the SDE has no separate ones, and its numbers sit above the core&#39;s on every line. Coverage says a line ran; the mutation table below says whether a test would notice it changing.</p><table tabindex="0"><thead><tr><th>Specification (<code>npm run spec:audit:verbose</code>, <code>features/sde/</code>)</th><th>Count</th></tr></thead><tbody><tr><td>Feature files</td><td>23, all on the step library (<code>tests/bdd/specs/sde/</code>, <code>tests/bdd/steps/</code>); none on legacy <code>defineFeature</code> files</td></tr><tr><td><code>Rule:</code> requirements</td><td>162, one EARS <code>shall</code> each</td></tr><tr><td>Scenarios</td><td>227 <code>Scenario</code>, no <code>Scenario Outline</code></td></tr><tr><td>Audit result</td><td>23 of 23 pass; <code>scripts/spec/spec-audit-exceptions.json</code> lists no SDE file</td></tr><tr><td>Method coverage (<code>npm run spec:coverage:sde:ci</code>)</td><td>96 of 96 <code>IStaticDataProvider</code> methods reached by a Rule or a bound step; <code>scripts/sde/sde-spec-coverage-baseline.json</code> is empty, so a method that loses its Rule fails CI</td></tr></tbody></table><p>The feature files run from <code>0001-static-data-lookup</code> to <code>0023-sde-ingestion</code>: the entity families in the interface&#39;s order (types, universe, market, dogma, characters, NPC organisations, presentation tables, industry, mission content, generic access), then loading, the optional peers, the <code>./sde/memory</code> entry and ingestion. The largest are <code>0023-sde-ingestion</code> (33 Rules, 43 scenarios), <code>0014-sde-npc-organisations</code> (16, 25) and <code>0020-sde-loading</code> (14, 19).</p><h2 id="where-the-scores-stand" tabindex="-1">Where the scores stand <a class="header-anchor" href="#where-the-scores-stand" aria-label="Permalink to &quot;Where the scores stand&quot;">​</a></h2><p>Three mutation runs score the SDE, each with its own shard and its own floors, ratcheted the way the core&#39;s are (<code>guides/TESTING.md</code>, &quot;Where the scores stand&quot;): a complete nightly raises a floor to that night&#39;s score and never lowers one, and a pull request cannot lower or remove one.</p><p>Track S Run M (<a href="https://github.com/lgriffin/ESI.ts/issues/458" target="_blank" rel="noreferrer">#458</a>, 2026-10-07 and 08) took every SDE directory to 90 or above on both the unit and the BDD-only run, one directory per pull request. Each pull request gave every surviving mutant a verdict: a new test or scenario kills it, or it is equivalent and carries <code>// Stryker disable next-line &lt;Mutator&gt;: &lt;reason&gt;</code> in the source, or it is listed below with the reason no test should name it. The scores are local runs with the nightly&#39;s own configs (<code>config/mutation/stryker.config.mjs</code> and <code>stryker.bdd.config.mjs</code>, <code>--mutate</code> narrowed to the directory), except the unit <code>src/sde</code> row, which Run M did not need to touch and which comes from the <a href="https://github.com/lgriffin/ESI.ts/actions/runs/36396694021" target="_blank" rel="noreferrer">nightly of 2026-09-28</a>.</p><table tabindex="0"><thead><tr><th>Directory</th><th style="text-align:right;">Unit score</th><th style="text-align:right;">Killed / valid</th><th style="text-align:right;">Unit floor</th><th>Pull request</th><th style="text-align:right;">BDD-only score</th><th style="text-align:right;">Killed / valid</th><th style="text-align:right;">BDD floor</th><th>Pull request</th></tr></thead><tbody><tr><td><code>src/sde</code></td><td style="text-align:right;">93.8%</td><td style="text-align:right;">15/16</td><td style="text-align:right;">85.6</td><td>(nightly)</td><td style="text-align:right;">100.0%</td><td style="text-align:right;">15/15</td><td style="text-align:right;">93</td><td>#611</td></tr><tr><td><code>src/sde/ingestion</code></td><td style="text-align:right;">100.0%</td><td style="text-align:right;">184/184</td><td style="text-align:right;">98</td><td>#608</td><td style="text-align:right;">97.6%</td><td style="text-align:right;">162/166</td><td style="text-align:right;">97</td><td>#612</td></tr><tr><td><code>src/sde/providers</code></td><td style="text-align:right;">100.0%</td><td style="text-align:right;">92/92</td><td style="text-align:right;">98</td><td>#607</td><td style="text-align:right;">90.5%</td><td style="text-align:right;">86/95</td><td style="text-align:right;">90</td><td>#610</td></tr></tbody></table><p>Before Run M the same directories scored 93.8 / 73.9 / 89.6 on the unit run and 50.0 / 59.0 / 58.6 BDD-only. The unit <code>src/sde</code> floor still holds its provisional seed, under its score, until a complete nightly raises it.</p><p><code>src/sde</code> is the root files: <code>clock.ts</code>, <code>errors.ts</code> and <code>optionalPeers.ts</code>. <code>src/sde/domain</code> holds only type declarations and Zod schemas and yields no valid mutants; <code>src/sde/testing</code> is excluded from both runs like <code>src/testing</code>. A mutant that crashes the runner (a missing-file check removed, a transform recursing on itself) counts as a runtime error and in no score. A unit run takes 10 to 15 minutes a directory on four cores; a BDD-only run over all of <code>src/sde</code> takes about 50, because the BDD dry run cannot narrow to related tests and runs every spec (<code>guides/TESTING.md</code>, &quot;How it works&quot; under Mutation testing).</p><p>Run M changed one behaviour on the way: the database builder took its columns from the first 50 records of a file, so a field that first appeared later was dropped from the table. It now scans every record (#609, with a Rule in <code>0023-sde-ingestion</code>). Nothing else in the source changed except equivalent-mutant annotations; the scores rose because the tests and scenarios grew.</p><p>The BDD-only survivors, each left on purpose because unit tests pin it and no scenario has a reason to name it:</p><table tabindex="0"><thead><tr><th>File</th><th style="text-align:right;">Survivors</th><th>Why no scenario kills it</th></tr></thead><tbody><tr><td><code>providers/order.ts</code></td><td style="text-align:right;">8</td><td><code>compareIds</code> on mixed number and string IDs (no SDE table mixes them), and the <code>&lt;=</code> / <code>&gt;=</code> / <code>0</code> forms that only differ for equal IDs, which keys never are</td></tr><tr><td><code>providers/yaml/SdeDataProvider.ts</code></td><td style="text-align:right;">1</td><td>The null skip when indexing a foreign key: no lookup asks for null</td></tr><tr><td><code>ingestion/SdeDatabaseBuilder.ts</code></td><td style="text-align:right;">2</td><td>The prepare-failure <code>catch</code>: it fires only when the output file already holds the table with other columns; a unit test rebuilds over such a file, and no scenario builds into a stale database</td></tr><tr><td><code>ingestion/transforms.ts</code></td><td style="text-align:right;">2</td><td>The array guard in <code>extractLocale</code> (an array has no <code>en</code> key) and the object test in <code>toSqliteValue</code> (only a function or symbol differs; YAML yields neither)</td></tr></tbody></table><p>The unit runs have no survivors in <code>providers</code> or <code>ingestion</code>; <code>src/sde</code>&#39;s one is in <code>optionalPeers.ts</code>.</p><table tabindex="0"><thead><tr><th>Type mutation (<a href="https://github.com/lgriffin/ESI.ts/actions/runs/36396694021/job/108875328069" target="_blank" rel="noreferrer">job</a>)</th><th style="text-align:right;">Score</th><th style="text-align:right;">Killed / valid</th><th style="text-align:right;">Invalid</th><th style="text-align:right;">Candidates</th><th style="text-align:right;">Floor (<code>config/mutation/type-thresholds.json</code>)</th></tr></thead><tbody><tr><td><code>./sde</code></td><td style="text-align:right;">29.5%</td><td style="text-align:right;">36/122</td><td style="text-align:right;">20</td><td style="text-align:right;">1,906</td><td style="text-align:right;">32 (below)</td></tr><tr><td><code>./sde/memory</code></td><td style="text-align:right;">28.0%</td><td style="text-align:right;">30/107</td><td style="text-align:right;">11</td><td style="text-align:right;">1,608</td><td style="text-align:right;">25</td></tr></tbody></table><p>Type mutation rewrites the built <code>dist/sde/*.d.ts</code> (a field made optional, a union widened, a parameter&#39;s type loosened) and runs tsd per mutant, on a sample of the candidates each night. <code>./sde</code> scored 29.5 against a floor of 32 that Run 8 seeded from a local sample; the nightly&#39;s sample is the one that counts, so the floor stays and the gap is the next tsd work, not a lowered ratchet. The core&#39;s entry points score between 4.1% (<code>./schemas</code>) and 30% (<code>./errors</code>) on the same night, so both SDE entry points sit at the top of the table.</p><h2 id="the-other-tiers" tabindex="-1">The other tiers <a class="header-anchor" href="#the-other-tiers" aria-label="Permalink to &quot;The other tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>What holds the SDE</th><th>Proven by</th></tr></thead><tbody><tr><td>Properties and fuzz</td><td><code>sde-provider-model.property.test.ts</code> drives <code>MemorySdeProvider</code> and <code>SdeDataProvider</code> against a model of the port over generated universes; <code>sde-transforms.property.test.ts</code> holds the ingestion transforms to their invariants (field-name normalisation is idempotent and reversible, locale extraction always answers a string, the record and metadata transforms match a naive recursive model); <code>sde-schema-fuzz.test.ts</code> throws arbitrary and near-valid records at every domain schema</td><td>Each model-based property must fail against its registered known-bad implementations, checked on every run (<code>tests/fuzz/support/property.ts</code>)</td></tr><tr><td>Real data, nightly</td><td><code>nightly-sde.yml</code> at 05:15 UTC downloads CCP&#39;s current export (cached per build), runs the 114 real-data tests with <code>SDE_REQUIRE_DATA=1</code>, <code>sde:drift</code> (the file list against the registry, every record&#39;s keys against its Zod schema), the four <code>examples/sde-*.ts</code>, then the six <code>sde/</code> benchmarks and the heap soak on the real export</td><td>Keeps one issue (&quot;sde: nightly real-data run failed or the export drifted&quot;) open while any job is red; last green run <a href="https://github.com/lgriffin/ESI.ts/actions/runs/36404108879" target="_blank" rel="noreferrer">36404108879</a></td></tr><tr><td>Isolation and layers</td><td><code>npm run lint:layers</code>: <code>src/sde</code> imports nothing of the package but <code>src/core/ports</code>, nothing outside it imports the SDE, and inside the module each layer imports only the layers listed for it in <code>SDE_LAYERS</code> (<code>config/eslint/layers.rules.cjs</code>): <code>ingestion</code> knows nothing of the providers, <code>domain</code> nothing of either; <code>memory-entry-bundle.test.ts</code> proves the shipped <code>./sde/memory</code> carries no file-system, YAML, ZIP or SQLite code</td><td><code>tests/tdd/layers/layers-lint.test.ts</code> lints a negative fixture at each real path; the bundle test checks itself against a known string</td></tr><tr><td>Determinism</td><td><code>npm run lint:determinism</code>: <code>src/sde/clock.ts</code> is the module&#39;s only reader of time, and the baseline lists no SDE exception</td><td><code>tests/tdd/determinism-lint/</code></td></tr><tr><td>Benchmarks and heap soak</td><td><code>tests/benchmark/sde.bench.ts</code>: load, <code>getType</code>, <code>getTypesByGroup</code> cold and indexed, name search by fragment and by whole name, on a seeded 50,000-type export; <code>sde-soak.ts</code> answers 100,000 lookups per cycle for three cycles and requires the heap back within 8 MiB or 5% after each <code>close()</code></td><td>An injected slowdown and an injected leak must be flagged (<code>tests/tdd/benchmark/sde-bench.test.ts</code>); the tasks ride <code>ci.yml</code>&#39;s <code>benchmarks</code> job and <code>nightly-benchmarks.yml</code></td></tr><tr><td>Package surface</td><td><code>npm run size</code>: <code>./sde</code> 45.4 kB ESM / 47.9 kB CJS and <code>./sde/memory</code> 20.7 kB / 22.5 kB budgets (<code>.size-limit.cjs</code>); <code>npm run test:docs-examples</code> type-checks every TypeScript block in <code>guides/sde/</code>, <code>guides/SDE.md</code> and <code>src/sde/README.md</code> against the packed package; <code>npm run api-report</code> tracks both entry points in <code>etc/esi.ts.api.md</code></td><td><code>size-limit</code> fails over budget; the doc-examples tier has negative fixtures in <code>tests/tdd/doc-examples/</code>; <code>api-report:semver</code> fails on a lost line without a breaking commit</td></tr><tr><td>Mutation on every PR</td><td><code>mutation-pr</code> in <code>ci.yml</code> mutates the changed <code>src/</code> files, SDE files included, plus any neighbour the nightly&#39;s incremental report does not cover, and refuses a pull request that lowers or removes a floor; the nightly&#39;s <code>mutation:ratchet</code> and <code>mutation:bdd:ratchet</code> hold the three SDE directories to the floors above</td><td><code>tests/mutation-fixture/</code> must leave survivors and kill at least one mutant</td></tr></tbody></table><h2 id="what-is-open" tabindex="-1">What is open <a class="header-anchor" href="#what-is-open" aria-label="Permalink to &quot;What is open&quot;">​</a></h2><ul><li><code>./sde</code> type mutation sits 2.5 points under its floor on the nightly sample. The floor does not move; the fix is more <code>expectError</code> assertions where the survivors cluster (<code>reports/type-mutation/type-mutation.md</code> from the run names them).</li><li>The Run M floors come from local runs. The next complete nightly re-measures all six and raises any floor that sits under its score; a nightly score under a floor fails the ratchet and is the next piece of work.</li><li>Two behaviours recorded by the programme and left for the maintainer, not the tests: an empty search fragment matches everything up to the limit, and a search limit below 1 answers one record (<code>ROADMAP.md</code>, Track S).</li></ul><p>Every floor here is a one-way ratchet: the next complete nightly raises a floor to its score, a pull request cannot lower one, and a directory without a floor fails the ratchet.</p>',27)])])}const p=t(r,[["render",a]]);export{u as __pageData,p as default};
